//! 🧰️ Emits every explicitly authored catalog, placed design, child and representation field.
use crate::standards::v1::subsets::kit::schema::snapshot::{SemioKitSnapshot,SemioKitType,SemioKitDesign,SemioKitPiece,SemioKitConnection};
use crate::standards::v1::subsets::base::io::sqlite::snapshot::native_encoding::{self,Writer};
use semio_framework_value::{ValueError,ValueRefusalKind};
use store::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotControl};
pub(crate) fn encode(snapshot:&SemioKitSnapshot,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::os_io::IoPayload,ValueError>{native_encoding::encode(encoding,"semio stdio.semio.kit.dsl v1\n","stdio.semio.kit.pack v1",control,|writer,encoding|fields(snapshot,writer,encoding))}
fn kind(value:&SemioKitType,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&value.id,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.name,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.category,encoding)?;writer.delimiter(b"]",encoding)}
fn piece(value:&SemioKitPiece,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&value.id,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.type_id,encoding)?;writer.delimiter(b",",encoding)?;writer.transform(&value.transform,encoding)?;writer.delimiter(b"]",encoding)}
fn connection(value:&SemioKitConnection,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&value.id,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.connecting_piece_id,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.connecting_port,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.connected_piece_id,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.connected_port,encoding)?;writer.delimiter(b"]",encoding)}
fn design(value:&SemioKitDesign,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&value.id,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.name,encoding)?;writer.delimiter(b",",encoding)?;writer.list(&value.pieces,encoding,|writer,value|piece(value,writer,encoding))?;writer.delimiter(b",",encoding)?;writer.list(&value.connections,encoding,|writer,value|connection(value,writer,encoding))?;writer.delimiter(b"]",encoding)}
pub(crate) fn fields(snapshot:&SemioKitSnapshot,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.entities(1)?;if encoding==SnapshotEncoding::Binary{writer.byte(1)?;}else{writer.bytes(b"schema=")?;}writer.string(&snapshot.schema,encoding)?;writer.delimiter(b"\ntypes=",encoding)?;writer.list(&snapshot.types,encoding,|writer,value|kind(value,writer,encoding))?;writer.delimiter(b"\ndesigns=",encoding)?;writer.list(&snapshot.designs,encoding,|writer,value|design(value,writer,encoding))?;writer.delimiter(b"\nobjects=",encoding)?;writer.list(&snapshot.objects,encoding,|writer,value|writer.child(value,encoding))?;writer.delimiter(b"\nmodels=",encoding)?;writer.list(&snapshot.models,encoding,|writer,value|writer.child(value,encoding))?;writer.delimiter(b"\nproperties=",encoding)?;writer.optional_child(&snapshot.properties,encoding)?;writer.delimiter(b"\nrepresentations=",encoding)?;writer.list(&snapshot.representations,encoding,|writer,value|writer.link(value,encoding))}
